#!/usr/bin/env node
/* Auto-generated by Coderbot. Runs one coding job (or a continuation of one)
 * inside GitHub Actions. Everything is driven by the app over HTTP, so the job
 * keeps running even when the user closes their browser. */
import { execSync } from "node:child_process";
import fs from "node:fs";
import path from "node:path";
import crypto from "node:crypto";

const JOB_ID = process.env.JOB_ID;
const JOB_SECRET = process.env.JOB_SECRET;
const APP_URL = process.env.APP_URL;
const BRANCH = process.env.WORKING_BRANCH;

if (!JOB_ID || !JOB_SECRET || !APP_URL) { console.error("missing env"); process.exit(1); }

const HEAD = { "Content-Type": "application/json", "X-Job-Id": JOB_ID, "X-Job-Secret": JOB_SECRET };
const api = (p, body) => fetch(APP_URL + p, { method: "POST", headers: HEAD, body: JSON.stringify(body ?? {}) })
  .then(async (r) => { if (!r.ok) throw new Error(p + " " + r.status + " " + (await r.text())); return r.json(); });

const log = async (line) => { console.log(line); try { await api("/api/public/jobs/log", { line }); } catch {} };

/* The activity feed the user sees in the app. */
let PHASE = "planning";
/* `agent` is { id, label } — omitted means the main agent. */
const event = async (kind, text, phase, agent) => {
  if (phase && !agent) PHASE = phase;
  try {
    await api("/api/public/jobs/event", {
      kind,
      text: String(text).slice(0, 3500),
      phase: phase || PHASE,
      agent_id: agent ? agent.id : "main",
      agent_label: agent ? agent.label : "Main agent",
    });
  } catch {}
};

const sh = (cmd, opts = {}) => execSync(cmd, { stdio: ["pipe", "pipe", "pipe"], encoding: "utf8", timeout: 1000 * 60 * 10, ...opts });

const MAX_STEPS = 200;
const START = Date.now();
const TIME_LIMIT_MS = 1000 * 60 * 60 * 5.2; // checkpoint well before the 6h wall

/* ---------------------------------- tools --------------------------------- */

const IGNORE_DIRS = new Set(["node_modules", ".git", "dist", "build", ".next", ".turbo", ".cache", "coverage", "out", ".venv", "venv", "target", ".output"]);
const TEXT_EXT = /\.(ts|tsx|js|jsx|mjs|cjs|py|rs|go|java|kt|swift|rb|php|c|cc|cpp|h|hpp|cs|scala|sh|bash|zsh|yml|yaml|json|md|mdx|txt|toml|ini|css|scss|html|svelte|vue|astro|sql|graphql|prisma)$/i;

function walk(dir, base = dir, out = []) {
  let names = [];
  try { names = fs.readdirSync(dir); } catch { return out; }
  for (const name of names) {
    if (IGNORE_DIRS.has(name)) continue;
    const p = path.join(dir, name);
    let st; try { st = fs.statSync(p); } catch { continue; }
    if (st.isDirectory()) walk(p, base, out);
    else if (TEXT_EXT.test(name) && st.size <= 200000) out.push({ path: path.relative(base, p).split(path.sep).join("/"), size: st.size });
  }
  return out;
}

function readFileSafe(p) { try { return fs.readFileSync(p, "utf8"); } catch { return null; } }
function writeFileSafe(p, content) { fs.mkdirSync(path.dirname(p) || ".", { recursive: true }); fs.writeFileSync(p, content, "utf8"); }

let TODOS = [];

const tools = [
  { type: "function", function: { name: "list_files", description: "List repository files. Optional substring filter on the path.",
    parameters: { type: "object", properties: { filter: { type: "string" } } } } },
  { type: "function", function: { name: "read_file", description: "Read a text file from the repo.",
    parameters: { type: "object", properties: { path: { type: "string" } }, required: ["path"] } } },
  { type: "function", function: { name: "search_code", description: "Search the repo for a regular expression. Returns path:line matches.",
    parameters: { type: "object", properties: { query: { type: "string" }, max_results: { type: "number" } }, required: ["query"] } } },
  { type: "function", function: { name: "write_file", description: "Create or overwrite a file with the COMPLETE new contents.",
    parameters: { type: "object", properties: { path: { type: "string" }, content: { type: "string" } }, required: ["path", "content"] } } },
  { type: "function", function: { name: "edit_file", description: "Replace an exact substring in a file. Prefer this for small edits.",
    parameters: { type: "object", properties: { path: { type: "string" }, find: { type: "string" }, replace: { type: "string" }, replace_all: { type: "boolean" } }, required: ["path", "find", "replace"] } } },
  { type: "function", function: { name: "delete_file", description: "Delete a file.",
    parameters: { type: "object", properties: { path: { type: "string" } }, required: ["path"] } } },
  { type: "function", function: { name: "run_shell", description: "Run a shell command from the repo root. Returns combined output (truncated).",
    parameters: { type: "object", properties: { cmd: { type: "string" } }, required: ["cmd"] } } },
  { type: "function", function: { name: "check_code", description: "Verify your work: runs the project's typecheck/lint/test scripts when they exist, plus static checks on changed files. Call this after editing and fix anything it reports.",
    parameters: { type: "object", properties: {} } } },
  { type: "function", function: { name: "update_plan", description: "Record or update your task list so the user can follow along. Each item has a title and a status of pending, in_progress or done.",
    parameters: { type: "object", properties: { todos: { type: "array", items: { type: "object", properties: { title: { type: "string" }, status: { type: "string" } }, required: ["title", "status"] } } }, required: ["todos"] } } },
  { type: "function", function: { name: "finish", description: "Call only when the task is complete and check_code is clean. Provide a user-facing summary and a commit message.",
    parameters: { type: "object", properties: { summary: { type: "string" }, commit_message: { type: "string" } }, required: ["summary", "commit_message"] } } },
];

const DELEGATE_TOOL = { type: "function", function: {
  name: "delegate",
  description: "Hand a self-contained part of the task to one of your sub-agents. It has the same file tools on this same checkout and runs to completion before returning its report. Never give two sub-agents the same files.",
  parameters: { type: "object", properties: {
    agent_id: { type: "string" },
    task: { type: "string", description: "Complete, self-contained instructions: what to change, which files, and how to verify." },
  }, required: ["agent_id", "task"] },
} };

/* Tools available to the model this step. `finish` and `delegate` are main-agent only. */
function toolsFor(kind, subAgents) {
  if (kind === "sub") return tools.filter((t) => t.function.name !== "finish");
  return subAgents && subAgents.length ? [...tools, DELEGATE_TOOL] : tools;
}

function changedFiles() {
  try {
    return sh("git status --porcelain").split("\n").map((l) => l.slice(3).trim()).filter(Boolean);
  } catch { return []; }
}

function pkgScripts() {
  const raw = readFileSafe("package.json");
  if (!raw) return {};
  try { return JSON.parse(raw).scripts ?? {}; } catch { return {}; }
}

function runCheckCode() {
  const problems = [];
  const files = changedFiles().filter((f) => TEXT_EXT.test(f));

  for (const f of files) {
    const content = readFileSafe(f);
    if (content == null) continue;
    if (!content.trim()) { problems.push(f + ": file is empty"); continue; }
    if (/^<{7}|^>{7}|^={7}$/m.test(content)) problems.push(f + ": leftover merge conflict markers");
    for (const pair of [["{", "}", "braces"], ["(", ")", "parens"], ["[", "]", "brackets"]]) {
      const o = content.split(pair[0]).length - 1;
      const c = content.split(pair[1]).length - 1;
      if (o !== c) problems.push(f + ": unbalanced " + pair[2] + " (" + o + " vs " + c + ")");
    }
    const importRe = /(?:from|require\()\s*['"](\.[^'"]+)['"]/g;
    let m;
    while ((m = importRe.exec(content))) {
      const spec = m[1];
      const base = path.normalize(path.join(path.dirname(f), spec));
      const cands = ["", ".ts", ".tsx", ".js", ".jsx", ".mjs", ".py", ".css", ".json", "/index.ts", "/index.tsx", "/index.js"].map((s) => base + s);
      if (!cands.some((c) => fs.existsSync(c))) problems.push(f + ": imports missing local file " + spec);
    }
  }

  const scripts = pkgScripts();
  const ran = [];
  for (const name of ["typecheck", "tsc", "lint", "test"]) {
    if (!scripts[name]) continue;
    ran.push(name);
    try { sh("npm run " + name + " --silent"); }
    catch (e) {
      const out = ((e.stdout || "") + (e.stderr || "")).toString().slice(-4000);
      problems.push("npm run " + name + " failed:\n" + out);
    }
  }
  return { changed: files, ran, problems, clean: problems.length === 0 };
}

function execTool(name, args) {
  try {
    if (name === "list_files") {
      let files = walk(process.cwd()).map((f) => f.path);
      if (args.filter) files = files.filter((f) => f.includes(args.filter));
      return files.slice(0, 800).join("\n") || "(no files)";
    }
    if (name === "read_file") { const c = readFileSafe(args.path); return c == null ? "ERR: not found" : c.slice(0, 60000); }
    if (name === "search_code") {
      let re; try { re = new RegExp(args.query, "i"); } catch (e) { return "ERR: bad pattern " + e.message; }
      const limit = Math.min(args.max_results || 60, 200);
      const hits = [];
      for (const f of walk(process.cwd())) {
        const c = readFileSafe(f.path);
        if (c == null) continue;
        const lines = c.split("\n");
        for (let i = 0; i < lines.length; i++) {
          if (re.test(lines[i])) { hits.push(f.path + ":" + (i + 1) + ": " + lines[i].slice(0, 200).trim()); if (hits.length >= limit) break; }
        }
        if (hits.length >= limit) break;
      }
      return hits.join("\n") || "(no matches)";
    }
    if (name === "write_file") { writeFileSafe(args.path, args.content ?? ""); return "OK wrote " + args.path; }
    if (name === "edit_file") {
      const c = readFileSafe(args.path);
      if (c == null) return "ERR: not found";
      if (!c.includes(args.find)) return "ERR: the `find` text does not appear in the file — read it again";
      const next = args.replace_all ? c.split(args.find).join(args.replace) : c.replace(args.find, args.replace);
      writeFileSafe(args.path, next);
      return "OK edited " + args.path;
    }
    if (name === "delete_file") { fs.unlinkSync(args.path); return "OK deleted " + args.path; }
    if (name === "run_shell") { return sh(args.cmd).slice(0, 8000) || "(no output)"; }
    if (name === "check_code") { return JSON.stringify(runCheckCode()).slice(0, 12000); }
    if (name === "update_plan") { TODOS = Array.isArray(args.todos) ? args.todos : []; return "OK"; }
    return "ERR: unknown tool";
  } catch (e) {
    return "ERR: " + ((e && (e.stderr || e.stdout) ? (e.stderr || e.stdout).toString() : (e && e.message) || String(e))).slice(0, 4000);
  }
}

/* --------------------------- provider / model call ------------------------- */

function chatRoute(spec, model) {
  if (model.startsWith("mistral:")) return { base: "https://api.mistral.ai/v1", key: spec.mistral_key, model: model.slice(8) };
  if (model.startsWith("groq:")) return { base: "https://api.groq.com/openai/v1", key: spec.groq_key, model: model.slice(5) };
  if (model.startsWith("nvidia:")) return { base: "https://integrate.api.nvidia.com/v1", key: spec.nvidia_key, model: model.slice(7) };
  return { base: "https://openrouter.ai/api/v1", key: spec.openrouter_key, model };
}

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

/* Per-minute rate limits: wait 10s and retry, forever. Any other limit
 * (quota / credits / context) stops the run with the provider's message. */
async function callModel(spec, messages, opts = {}) {
  const route = chatRoute(spec, opts.model || spec.model);
  const activeTools = opts.tools || toolsFor("main", spec.sub_agents);
  for (let attempt = 0; ; attempt++) {
    const res = await fetch(route.base + "/chat/completions", {
      method: "POST",
      headers: { "Content-Type": "application/json", Authorization: "Bearer " + route.key },
      body: JSON.stringify({ model: route.model, messages, tools: activeTools, tool_choice: "auto" }),
    });
    if (res.ok) return res.json();
    const text = (await res.text()).slice(0, 800);
    const isRpm = res.status === 429 && (/per.?minute|rpm|requests per|rate.?limit/i.test(text) || !/quota|credit|balance|billing/i.test(text));
    if (isRpm && attempt < 300) {
      await event("status", "Rate limited — waiting 10 seconds, then retrying.", undefined, opts.agent);
      await sleep(10000);
      continue;
    }
    throw new Error("Provider error " + res.status + ": " + text);
  }
}

/* Providers such as Groq reject assistant messages that carry extra fields
 * (e.g. `reasoning`, `executed_tools`) back on the next request, so only echo
 * the fields the chat-completions API defines. */
function sanitizeAssistant(msg) {
  const out = { role: "assistant", content: typeof msg.content === "string" ? msg.content : "" };
  if (Array.isArray(msg.tool_calls) && msg.tool_calls.length) {
    out.tool_calls = msg.tool_calls.map((c) => ({
      id: c.id,
      type: "function",
      function: { name: c.function && c.function.name, arguments: (c.function && c.function.arguments) || "{}" },
    }));
  }
  return out;
}

/* Keep the transcript small enough to carry across a checkpoint. */
function trimForCheckpoint(messages) {
  const out = messages.map((m) => (m.role === "tool" && typeof m.content === "string" && m.content.length > 4000
    ? { ...m, content: m.content.slice(0, 4000) + "\n…(truncated)" }
    : m));
  while (JSON.stringify(out).length > 400000 && out.length > 4) out.splice(1, 1);
  return out;
}

function verb(name, args) {
  if (name === "read_file") return "Read " + args.path;
  if (name === "list_files") return "Listed the repository files";
  if (name === "search_code") return 'Searched for "' + String(args.query || "").slice(0, 60) + '"';
  if (name === "write_file") return "Wrote " + args.path;
  if (name === "edit_file") return "Edited " + args.path;
  if (name === "delete_file") return "Deleted " + args.path;
  if (name === "run_shell") return "Ran " + String(args.cmd || "").slice(0, 90);
  if (name === "check_code") return "Checked the code I changed for problems";
  if (name === "update_plan") return "Updated the plan: " + (args.todos || []).map((t) => t.title).join(" · ").slice(0, 200);
  if (name === "delegate") return "Delegated to " + (args.agent_id || "a sub-agent");
  return name;
}

function phaseFor(name, sawCheck) {
  if (name === "write_file" || name === "edit_file" || name === "delete_file") return sawCheck ? "debugging" : "coding";
  if (name === "check_code") return "checking";
  if (name === "run_shell") return sawCheck ? "debugging" : "coding";
  return PHASE;
}

/* ----------------------------------- main --------------------------------- */

/* Pull the user's uploaded files into the checkout so code can use them. */
async function fetchAttachments(spec) {
  const list = spec.attachments || [];
  if (!list.length) return [];
  const readable = [];
  fs.mkdirSync("uploads", { recursive: true });
  for (const a of list) {
    const safe = String(a.name).replace(/[^\w.\-]+/g, "_");
    try {
      const res = await fetch(a.url);
      if (!res.ok) throw new Error("download " + res.status);
      const buf = Buffer.from(await res.arrayBuffer());
      fs.writeFileSync(path.join("uploads", safe), buf);
      await event("action", "Saved upload uploads/" + safe, PHASE);
      if (!a.code_only) readable.push({ name: safe, mime: a.mime_type || "", buf });
    } catch (e) {
      await log("attachment failed " + safe + ": " + ((e && e.message) || e));
    }
  }
  return readable;
}

/* Text/image content for the uploads the AI is allowed to read. */
function attachmentMessages(readable) {
  const out = [];
  const textParts = [];
  const imageParts = [];
  for (const a of readable) {
    if (/^image\//.test(a.mime)) {
      imageParts.push({ type: "image_url", image_url: { url: "data:" + a.mime + ";base64," + a.buf.toString("base64") } });
    } else {
      textParts.push("--- uploads/" + a.name + " ---\n" + a.buf.toString("utf8").slice(0, 40000));
    }
  }
  if (textParts.length) {
    out.push({ role: "user", content: "Files the user uploaded (also saved under uploads/):\n\n" + textParts.join("\n\n") });
  }
  if (imageParts.length) {
    out.push({ role: "user", content: [{ type: "text", text: "Images the user uploaded (also saved under uploads/)." }, ...imageParts] });
  }
  return out;
}

/* A sub-agent: same tools, same checkout, its own model and activity feed. */
async function runSubAgent(spec, agent, task) {
  const subTools = toolsFor("sub", spec.sub_agents);
  const messages = [
    { role: "system", content:
      "You are " + agent.label + ", a sub-agent of Coderbot working inside GitHub Actions on the repository checkout. " +
      "Do only the part of the task you were given — do not touch unrelated files, do not commit. " +
      (agent.instructions ? "Your standing scope: " + agent.instructions + ". " : "") +
      "Use your tools to read, search, write and edit files, then run check_code and fix what it reports. " +
      "When your part is done, reply with a plain-text report of exactly what you changed (no tool call)." },
    { role: "user", content: task },
  ];
  await event("status", "Started on: " + String(task).slice(0, 160), "coding", agent);
  for (let step = 0; step < 60; step++) {
    const body = await callModel(spec, messages, { model: agent.model, tools: subTools, agent });
    const msg = body.choices && body.choices[0] && body.choices[0].message;
    if (!msg) return "Sub-agent " + agent.id + " returned no message.";
    messages.push(sanitizeAssistant(msg));
    if (msg.content && String(msg.content).trim()) await event("thought", String(msg.content).trim().slice(0, 800), undefined, agent);
    const calls = msg.tool_calls || [];
    if (!calls.length) {
      await event("status", "Finished its part.", "done", agent);
      return String(msg.content || "Done.").slice(0, 6000);
    }
    for (const c of calls) {
      let args = {};
      try { args = JSON.parse((c.function && c.function.arguments) || "{}"); } catch {}
      const name = c.function.name;
      await event("action", verb(name, args), undefined, agent);
      const out = name === "delegate" ? "ERR: sub-agents cannot delegate" : execTool(name, args);
      messages.push({ role: "tool", tool_call_id: c.id, content: String(out).slice(0, 40000) });
    }
  }
  await event("status", "Hit its step limit.", "done", agent);
  return "Sub-agent " + agent.id + " hit its step limit; check its work.";
}

async function main() {
  await log("Claiming job " + JOB_ID);
  const spec = await api("/api/public/jobs/claim");
  await log("Model: " + spec.model + " · mode: " + (spec.mode || "build"));

  if (spec.job_type === "index") { await runIndex(spec); return; }

  const resumed = spec.checkpoint && Array.isArray(spec.checkpoint.messages) && spec.checkpoint.messages.length > 0;
  const readable = resumed ? [] : await fetchAttachments(spec);
  const messages = resumed
    ? spec.checkpoint.messages
    : [{ role: "system", content: spec.system }, ...attachmentMessages(readable), ...spec.messages];
  const subAgents = spec.sub_agents || [];
  if (resumed) {
    TODOS = spec.checkpoint.todos || [];
    messages.push({ role: "user", content: "The previous run hit the GitHub Actions time limit and was checkpointed. Your uncommitted work was pushed to the branch and is present in this checkout. Continue where you left off until the task is complete." });
    await event("status", "Resumed after checkpoint — continuing the task.", "coding");
  } else {
    await event("status", "Runner started on GitHub Actions in " + (spec.mode || "build") + " mode.", "planning");
    await event("thought", "Working out what this task needs and which files matter.", "planning");
  }

  let done = null;
  let sawCheck = false;
  let sawWrite = false;

  for (let step = 0; step < MAX_STEPS; step++) {
    if (Date.now() - START > TIME_LIMIT_MS) {
      await checkpointAndContinue(messages);
      return;
    }
    const body = await callModel(spec, messages);
    const msg = body.choices && body.choices[0] && body.choices[0].message;
    if (!msg) throw new Error("The model returned no message");
    messages.push(sanitizeAssistant(msg));

    if (msg.content && String(msg.content).trim()) {
      await event("thought", String(msg.content).trim().slice(0, 800));
    }

    const calls = msg.tool_calls || [];
    if (calls.length === 0) {
      done = { summary: msg.content || "Done.", commit_message: "Coderbot update" };
      break;
    }

    for (const c of calls) {
      let args = {};
      try { args = JSON.parse((c.function && c.function.arguments) || "{}"); } catch {}
      const name = c.function.name;
      if (name === "finish") {
        // Refuse to finish with unverified edits: force one verification pass.
        if (sawWrite && !sawCheck) {
          sawCheck = true;
          await event("action", "Checked the code I changed for problems", "checking");
          const result = runCheckCode();
          messages.push({ role: "tool", tool_call_id: c.id, content: "Before finishing, verification ran automatically: " + JSON.stringify(result).slice(0, 8000) + (result.clean ? "\nClean — you may call finish again." : "\nFix these problems, then call check_code again.") });
          if (!result.clean) await event("status", "Found problems — fixing them.", "debugging");
          continue;
        }
        done = { summary: args.summary, commit_message: args.commit_message };
        messages.push({ role: "tool", tool_call_id: c.id, content: "ok" });
        break;
      }
      if (name === "write_file" || name === "edit_file" || name === "delete_file") sawWrite = true;
      if (name === "check_code") sawCheck = true;
      if (name === "delegate") {
        const agent = subAgents.find((a) => a.id === args.agent_id) || subAgents[0];
        if (!agent) {
          messages.push({ role: "tool", tool_call_id: c.id, content: "ERR: no sub-agents are configured" });
          continue;
        }
        await event("action", "Delegated to " + agent.label + ": " + String(args.task || "").slice(0, 120), "coding");
        let report;
        try { report = await runSubAgent(spec, agent, String(args.task || "")); }
        catch (e) { report = "Sub-agent failed: " + ((e && e.message) || e); await event("error", report, PHASE, agent); }
        sawWrite = true;
        sawCheck = false; // sub-agent work must be verified by the main agent
        messages.push({ role: "tool", tool_call_id: c.id, content: (agent.label + " reported:\n" + report).slice(0, 20000) });
        continue;
      }
      const nextPhase = phaseFor(name, sawCheck);
      await event("action", verb(name, args), nextPhase);
      const out = execTool(name, args);
      if (name === "check_code") {
        const clean = out.includes('"clean":true');
        await event(clean ? "status" : "status", clean ? "Checks are clean." : "Found problems — fixing them.", clean ? "checking" : "debugging");
      }
      await log("→ " + name + " " + String(args.path || args.cmd || args.query || "").slice(0, 100));
      messages.push({ role: "tool", tool_call_id: c.id, content: String(out).slice(0, 40000) });
    }
    if (done) break;
  }

  if (!done) {
    await checkpointAndContinue(messages);
    return;
  }

  await commitAndComplete(done);
}

async function gitCommit(message) {
  sh("git config user.email 'coderbot@users.noreply.github.com'");
  sh("git config user.name 'Coderbot'");
  const status = sh("git status --porcelain");
  if (!status.trim()) return null;
  sh("git add -A");
  sh("git commit -m " + JSON.stringify(message));
  sh("git pull --rebase origin " + BRANCH + " || true");
  sh("git push origin HEAD:" + BRANCH);
  return sh("git rev-parse HEAD").trim();
}

async function commitAndComplete(done) {
  try {
    const sha = await gitCommit(done.commit_message || "Coderbot update");
    if (sha) {
      await event("status", "Committed and pushed " + sha.slice(0, 7) + ".", "done");
      await api("/api/public/jobs/complete", { status: "completed", summary: done.summary || "Done.", commit_sha: sha });
    } else {
      await event("status", "Finished — no file changes were needed.", "done");
      await api("/api/public/jobs/complete", { status: "completed", summary: done.summary || "No changes." });
    }
  } catch (e) {
    await event("error", "Commit/push failed: " + ((e && e.message) || e), "done");
    await api("/api/public/jobs/complete", { status: "failed", error: String((e && e.message) || e) });
    process.exit(1);
  }
}

/* Save state, push work in progress, and ask the app to dispatch a follow-up
 * run so long tasks survive the 6h GitHub Actions limit. */
async function checkpointAndContinue(messages) {
  await event("status", "Approaching the GitHub Actions time limit — saving progress and starting a fresh run.", PHASE);
  try { await gitCommit("Coderbot checkpoint (work in progress)"); } catch (e) { await log("checkpoint push failed: " + ((e && e.message) || e)); }
  const checkpoint = { messages: trimForCheckpoint(messages), todos: TODOS };
  await api("/api/public/jobs/checkpoint", { checkpoint });
  const res = await api("/api/public/jobs/continue", { checkpoint });
  await event("status", "Continuing in a new GitHub Actions run.", PHASE);
  await log("continuation job " + (res.job_id || "?"));
}

/* ============================ Indexing mode ============================ */

function sha1(s) { return crypto.createHash("sha1").update(s).digest("hex"); }

function chunkText(text, target = 3200, overlap = 400) {
  const chunks = [];
  let i = 0;
  while (i < text.length) {
    const end = Math.min(text.length, i + target);
    chunks.push(text.slice(i, end));
    if (end === text.length) break;
    i = end - overlap;
  }
  return chunks;
}

function extractSymbols(text) {
  const out = [];
  const rx = /^\s*export\s+(?:async\s+)?(?:function|class|const|let|var|interface|type|enum)\s+([A-Za-z_$][\w$]*)/gm;
  let m;
  while ((m = rx.exec(text)) && out.length < 40) out.push({ name: m[1], kind: "export", line: text.slice(0, m.index).split("\n").length });
  return out;
}

async function embedBatch(spec, inputs) {
  const base = spec.embedding_provider === "mistral" ? "https://api.mistral.ai/v1"
    : spec.embedding_provider === "nvidia" ? "https://integrate.api.nvidia.com/v1"
    : "https://openrouter.ai/api/v1";
  for (let attempt = 0; ; attempt++) {
    const res = await fetch(base + "/embeddings", {
      method: "POST",
      headers: { "Content-Type": "application/json", Authorization: "Bearer " + spec.embedding_key },
      body: JSON.stringify({ model: spec.embedding_model, input: inputs }),
    });
    if (res.ok) { const body = await res.json(); return body.data.map((d) => d.embedding); }
    const text = (await res.text()).slice(0, 300);
    if (res.status === 429 && attempt < 300) { await sleep(10000); continue; }
    throw new Error(spec.embedding_provider + " embed " + res.status + " " + text);
  }
}

async function summarize(spec, filePath, snippet) {
  const route = chatRoute(spec, spec.model);
  const res = await fetch(route.base + "/chat/completions", {
    method: "POST",
    headers: { "Content-Type": "application/json", Authorization: "Bearer " + route.key },
    body: JSON.stringify({
      model: route.model,
      messages: [
        { role: "system", content: "You summarize source files in ONE sentence (max 40 words): purpose + key exports. No preamble." },
        { role: "user", content: "Path: " + filePath + "\n\n" + snippet.slice(0, 6000) },
      ],
      max_tokens: 100,
      temperature: 0.2,
    }),
  });
  if (!res.ok) return "";
  const body = await res.json();
  return ((body.choices && body.choices[0] && body.choices[0].message.content) || "").trim().slice(0, 300);
}

async function runIndex(spec) {
  const files = walk(process.cwd());
  await log("Indexing " + files.length + " files with " + spec.embedding_model + "…");
  await api("/api/public/jobs/index-progress", { current: 0, total: files.length });
  let done = 0;
  for (const f of files) {
    try {
      const content = fs.readFileSync(f.path, "utf8");
      const sha = sha1(content);
      const chunks = chunkText(content);
      const embeddings = [];
      for (let i = 0; i < chunks.length; i += 32) embeddings.push(...(await embedBatch(spec, chunks.slice(i, i + 32))));
      const summary = await summarize(spec, f.path, content);
      await api("/api/public/jobs/index-batch", {
        file: { path: f.path, sha, size: f.size, language: (f.path.split(".").pop() || "").toLowerCase() || null, summary, symbols: extractSymbols(content) },
        chunks: chunks.map((c, i) => ({ chunk_index: i, content: c, embedding: embeddings[i], token_count: Math.round(c.length / 4) })),
      });
    } catch (e) {
      await log("skip " + f.path + ": " + String((e && e.message) || e).slice(0, 200));
    }
    done++;
    if (done % 5 === 0 || done === files.length) {
      await api("/api/public/jobs/index-progress", { current: done, total: files.length });
      await log("indexed " + done + "/" + files.length);
    }
  }
  await api("/api/public/jobs/complete", { status: "completed", summary: "Indexed " + done + " files." });
}

main().catch(async (e) => {
  const msg = String((e && e.message) || e);
  await log("FATAL " + msg);
  try { await event("error", msg, PHASE); } catch {}
  try { await api("/api/public/jobs/complete", { status: "failed", error: msg }); } catch {}
  process.exit(1);
});
